INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/drakos:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/drakos', 'effet', 'texte_different', 'modes', '(Action) Permet une attaque de souffle de l''élément de la magie innée, inflige 3d6/NPM dégâts et possède une portée de 4. Elle ne bénéficie pas des boost de dégats donner par le mode hyper ou autre (mais est influencée par les postures). Demande un jet qui est choisi entre toutes les compétences d''attaques disponible.', 'fiche (Race!W)', 'Les écailles absorbe les dégâts subits du même élément que la magie inné et les convertis en Barrière.', 'Mode hyper de la race Drakos : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/elfe-argente:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/elfe-argente', 'effet', 'texte_different', 'modes', 'Toutes les attaques magiques sont imparable.', 'fiche (Race!W)', 'Toutes les sortilèges d''attaques sont imparable.', 'Mode hyper de la race Elfe argenté : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/elfe-noir:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/elfe-noir', 'effet', 'texte_different', 'modes', 'Permet de synthétiser un poison unique sur l''arme principale, inflige "poison 1" pendant tout le monde hyper. L''ennemi doit faire un jet de vigueur tout les débuts de tour pour ne pas encaisser les dégâts.', 'fiche (Race!W)', 'Permet de synthétiser un poison unique sur l''arme principale, inflige "poison 1" pendant tout le mode hyper. L''ennemi doit faire un jet de vigueur tout les début de tour pour ne pas encaisser les dégâts.', 'Mode hyper de la race Elfe noir : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/goleois:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/goleois', 'effet', 'texte_different', 'modes', 'Augmente les dégâts de tous les alliés de 5, le temps du mode hyper.', 'fiche (Race!W)', 'Augmente les dégâts de tous les alliés de 5.', 'Mode hyper de la race Goleois : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/hujin:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/hujin', 'effet', 'texte_different', 'modes', 'Diminue d''un cran les dés des attaques physiques ou magiques subit', 'fiche (Race!W)', 'Divise les dégâts physiques et magiques reçu par 2.', 'Mode hyper de la race Hujin : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/jackalope:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/jackalope', 'effet', 'texte_different', 'modes', '+3 Vitesse', 'fiche (Race!W)', 'Les terrains, météos ou effets qui retire de la Vitesse et/ou de l''Initiative ne fonctionne pas sur lui.', 'Mode hyper de la race Jackalope : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/lamia:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/lamia', 'effet', 'texte_different', 'modes', 'Permet de cracher un venin à 3PO qui est capable d''empoisonné et de paralysé pendant 3 tours, oblige 2 jet de vigueur pour résister au deux effets.', 'fiche (Race!W)', 'Permet de cracher un venin à 3PO qui est capable d''empoisonné 2 et de paralysé 2 pendant 3 tours, oblige 2 jet de vigueur pour résister au deux effets.', 'Mode hyper de la race Lamia : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/marcass:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/marcass', 'effet', 'texte_different', 'modes', 'Les AP et AM naturels s’ajoutent à toute réduction de dégâts, quel que soit le type d’attaque.', 'fiche (Race!W)', 'Les AP et AM réduit les dégâts infligés par les altérations d''états.', 'Mode hyper de la race Marcass : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/mort-vivant:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/mort-vivant', 'effet', 'texte_different', 'modes', 'Régénère 20% de santé au début de son tour.', 'fiche (Race!W)', 'Régénère 20 Santé par tour.', 'Mode hyper de la race Mort-vivant : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/nain:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/nain', 'effet', 'texte_different', 'modes', '2d de dégâts physiques en plus. Le sort malédiction ne marche.', 'fiche (Race!W)', '2d de dégâts physiques en plus. Le sort malédiction ne marche pas.', 'Mode hyper de la race Nain : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/namazu:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/namazu', 'effet', 'texte_different', 'modes', 'La prochaine attaque avec une arme inflige "saignement 1" pendant tout le mode hyper. L''ennemi doit faire un jet de vigueur tous les début de tour pour ne pas encaisser les dégâts.', 'fiche (Race!W)', 'Double les AP donné par l''armure naturelle (+6 AP au lieu de +3).', 'Mode hyper de la race Namazu : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/olwman:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/olwman', 'effet', 'texte_different', 'modes', 'Peut se déplacement gratuitement de 2 cases et ceux n''importe quand durant le tour. (1 fois par tour)', 'fiche (Race!W)', '+3 en vitesse', 'Mode hyper de la race Olwman : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('mode_hyper_effet:classeur_modes:races/satyre:effet:texte_different:modes:fiche (Race!W)', 'mode_hyper_effet', 'classeur_modes:races/satyre', 'effet', 'texte_different', 'modes', 'Impose un malus de 10% (augmente de 5% au niveau 10 globale) à tous les jets des ennemis dans un rayon de 5 cases ou moins.', 'fiche (Race!W)', 'La cible lance un d4, 1 = État [Étourdi], 2 = État [Poison stade 2], 3 = État [Sommeil], 4 = État [Couardise]', 'Mode hyper de la race Satyre : le classeur « Mode hyper et co » et la « Capacité Hyper » de la feuille Race de la fiche (race.capacite_hyper) n''ont pas le même texte', 'annexes', 'Mode hyper et co › Mode Hyper ; Fiche auto V15.2.2 › Race › W');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('page:guide/resistance-faiblesse-magie:en-tête:texte_different:guide:fiche', 'page', 'guide/resistance-faiblesse-magie', 'en-tête', 'texte_different', 'guide', 'Cible \ Attaque', 'fiche', 'ligne = attaque, colonne = cible', 'L''en-tête de la table du guide dit « Cible \ Attaque » ; ses 169 cellules coïncident avec la matrice de la fiche lue dans l''autre sens (ligne = magie qui attaque) : 1 écart(s) dans ce sens contre 33 dans le sens de l''en-tête', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Résistance/Faiblesse Magie');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('page:ressources/machine-de-guerresiege:Q40:forme_non_reconnue:ressources_craft', 'page', 'ressources/machine-de-guerresiege', 'Q40', 'forme_non_reconnue', 'ressources_craft', NULL, NULL, NULL, 'cellule isolée « Vent » hors de tout tableau de l''onglet : non rattachée à une machine', 'craft', 'Ressources et Craft › Machine de GuerreSiège › Q40');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:defensif:texte:Parade/Esquive illimité:texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:defensif', 'texte:Parade/Esquive illimité', 'texte_different', 'guide_mj', 'Permet d''esquiver ou de parer tous les coups dans un tour MAIS dès que le nombre de parade/esquive est au delà de deux = chaque coup va diminuer la réussite de la prochaine parade/esquive de 10%.', 'guide_fiche', 'Permet d''esquiver ou de parer tous les coups dans un tour MAIS chaque coup va diminuer la réussite de la prochaine parade/esquive de 10%.', 'Posture Défensif, effet « Parade/Esquive illimité » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:defensif:texte:Provocation:texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:defensif', 'texte:Provocation', 'texte_different', 'guide_mj', 'Permet en échange d''un bon dialogue ou d''un jet de diplomatie, intimidation ou manipulation réussi, d''obliger un adversaire à venir vous attaquer que vous pendant 1 tour.', 'guide_fiche', 'Permet en échange d''un bon dialogue et d''un jet de diplomatie, intimidation ou manipulation réussi, d''obliger un adversaire à venir vous attaquer que vous pendant 1 tour.', 'Posture Défensif, effet « Provocation » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:focus:texte:Augmente le cran de dé de dégâts/soin:texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:focus', 'texte:Augmente le cran de dé de dégâts/soin', 'texte_different', 'guide_mj', 'Permet d’augmenter d’un cran la nature des dés qui seront lancés pour le sortilèges (le D6 devient D8, etc…en sachant qu’il n’y pas plus haut que le D20)', 'guide_fiche', 'Permet d’augmenter d’un cran la nature des dés qui seront lancés pour le sortilège (le D6 devient D8, etc…en sachant qu’il n’y pas plus haut que le D20)', 'Posture Focus, effet « Augmente le cran de dé de dégâts/soin » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:offensif:texte:+5% à la réussite critique:texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:offensif', 'texte:+5% à la réussite critique', 'texte_different', 'guide_mj', 'La réussite critique (ou coup critique) est de base à 5 ou moins, grâce à la posture offensif, cette réussite critique monte à 10 ou moins.', 'guide_fiche', 'La réussite critique (ou coup critique) est de bas à 5 ou moins, grâce à la posture offensif, cette réussite critique monte à 10 ou moins.', 'Posture Offensif, effet « +5% à la réussite critique » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:symbiose:effet:+1 tour d''effet pour les effets secondaires avec des tours:valeur_absente:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:symbiose', 'effet:+1 tour d''effet pour les effets secondaires avec des tours', 'valeur_absente', 'guide_mj', 'Si votre sortilège possède un effet qui dure sur plusieurs tours, la posture permet d''ajouter 1 tour gratuitement.', 'guide_fiche', NULL, 'Posture Symbiose : l''effet « +1 tour d''effet pour les effets secondaires avec des tours » n''est écrit que dans la source « guide_mj »', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:symbiose:texte:+5 dégâts/soin avec une magie:texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:symbiose', 'texte:+5 dégâts/soin avec une magie', 'texte_different', 'guide_mj', 'Permet d''infliger un bonus de dégâts de +5 ou alors un bonus de +5 avec un sort de soin. Cela augmente de +2 tous les niveaux de puissance magique (le premier niveau ne compte pas)', 'guide_fiche', 'Permet d''infliger un bonus de dégâts de +6 ou alors un bonus de +5 avec un sort de soin. Cela augmente de +2 tous les niveaux de puissance magique (le premier niveau ne compte pas)', 'Posture Symbiose, effet « +5 dégâts/soin avec une magie » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:symbiose:texte:Impossible d''utiliser les objets et armes (sauf forgemagie):texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:symbiose', 'texte:Impossible d''utiliser les objets et armes (sauf forgemagie)', 'texte_different', 'guide_mj', 'Vous êtes quasiment un élémentaire, les armes physiques et les objets ne sont pas dans votre optique (“Forgemagie”, “Forge de ses morts”, Bâton magique et les parchemins ne sont pas interdit)', 'guide_fiche', 'Vous êtes quasiment un élémentaire, les armes physiques et les objets ne sont pas dans votre optique (la forgemagie est un sort qui permet de créer des armes faites de magie, donc c''est bon)', 'Posture Symbiose, effet « Impossible d''utiliser les objets et armes (sauf forgemagie) » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
INSERT INTO ecart_source (id, entite_table, entite_id, champ, nature, source_a, valeur_a, source_b, valeur_b, detail, origine, source_ref) VALUES ('posture:guide/postures#posture:vigilance:texte:Peut anticiper les actions adverses:texte_different:guide_mj:guide_fiche', 'posture', 'guide/postures#posture:vigilance', 'texte:Peut anticiper les actions adverses', 'texte_different', 'guide_mj', 'Permet grâce un jet d''observation d''avoir une info intéressante sur la prochaine action de l''adversaire, voir le mj pour ça.', 'guide_fiche', 'Permet grâce un jet d''observation/distinction d''avoir une info intéressante sur la prochaine action de l''adversaire, voir le mj pour ça.', 'Posture Vigilance, effet « Peut anticiper les actions adverses » : la page « Postures » et la page « Tableau Posture » n''ont pas le même texte', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures ; Google Doc « Créer sa fiche de personnage » › Tableau Posture');
